(
  '392b237d-c03e-563f-8899-bd0a3c5166ac',
  'dumbbell fly',
  'dumbbell fly',
  'chest',
  'dumbbell',
  'pectorals',
  ARRAY['deltoids']::text[],
  ARRAY['Step:1 Settle onto a bench with a dumbbell in each hand, palms facing each other.', 'Step:2 Reach your arms straight up over your chest, with a slight bend in your elbows.', 'Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.', 'Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Step:5 Keep the elbow angle nearly unchanged through the arc.', 'Step:6 Open the arms back along the same arc without dropping the load.']::text[],
  'https://static.exercisedb.dev/media/yz9nUhF.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '39359fe9-fb0e-532c-83d5-3bdadfe24a64',
  'dumbbell fly stabilityball',
  'dumbbell fly on exercise ball',
  'chest',
  'dumbbell',
  'pectorals',
  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Take a seat on an exercise ball and hold a dumbbell in each hand.', 'Step:2 Step your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.', 'Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.', 'Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Open the arms back along the same arc without dropping the load.']::text[],
  'https://static.exercisedb.dev/media/Lt3iWnf.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '23604955-6901-52f4-930a-f48fb2de6c45',
  'dumbbell flyes',
  'Dumbbell Flyes',
  'chest',
  'dumbbell',
  'chest',
  '{}'::text[],
  ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.', 'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary, the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '6d72a1ca-fa6b-563e-ae49-e33fc2c1e47c',
  'dumbbell extension forward lunge triceps',
  'dumbbell forward lunge triceps extension',
  'triceps',
  'dumbbell',
  'triceps',
  ARRAY['deltoids', 'core']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.', 'Step:2 Step forward with your right foot, lowering your body into a lunge position.', 'Step:3 Set your stance wide enough to balance before bending either knee.', 'Step:4 Step into the movement and bend both knees, keeping your front foot planted.', 'Step:5 Keep the front foot planted and avoid collapsing inward at the knee.', 'Step:6 Push through the lead foot to return to the start, then change legs as planned.']::text[],
  'https://static.exercisedb.dev/media/XalXcvM.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'bd72e8df-a7a1-57ed-90cc-3e8669823ffe',
