  'JohnPreston'
),
(
  '75512abc-fadb-5694-9788-052fc0bee424',
  'dumbbell front raise',
  'dumbbell front raise',
  'shoulders',
  'dumbbell',
  'deltoids',
  ARRAY['biceps', 'trapezius']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your thighs.', 'Step:2 With your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.', 'Step:3 Start with a manageable load and a small bend in the elbows.', 'Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Step:5 Stop near shoulder height rather than shrugging to lift higher.', 'Step:6 Lower the arms slowly to your sides without swinging the weight.']::text[],
  'https://static.exercisedb.dev/media/3eGE2JC.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'e0da9477-efad-5d0b-85af-530e100b637d',
  'dumbbell front squat',
  'Dumbbell Front Squat',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'AlucardEvil40'
),
(
  'd835946b-88b0-5820-b2a4-762e750cfa90',
  'can dumbbell lateral raise',
  'dumbbell full can lateral raise',
  'shoulders',
  'dumbbell',
  'deltoids',
  ARRAY['trapezius', 'rotator cuff']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your body.', 'Step:2 Keep your spine in a comfortable neutral position and Brace your trunk.', 'Step:3 Start with a manageable load and a small bend in the elbows.', 'Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Step:5 Stop near shoulder height rather than shrugging to lift higher.', 'Step:6 Lower the arms slowly to your sides without swinging the weight.']::text[],
  'https://static.exercisedb.dev/media/AQ0mC4Y.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '83a4426f-2e54-50a2-aca3-8ed339f1564e',
  'dumbbell goblet squat',
  'dumbbell goblet squat',
  'legs',
  'dumbbell',
  'quadriceps',
  ARRAY['glutes', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a dumbbell vertically against your chest with both hands.', 'Step:2 With your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
  'https://static.exercisedb.dev/media/yn8yg1r.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '1c3d339e-1619-59db-a436-ea45bd7fea82',
  'curl dumbbell hammer',
  'dumbbell hammer curl',
  'biceps',
  'dumbbell',
  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Stand tall with a dumbbell in each hand, palms facing your torso.', 'Step:2 Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Curl with palms facing each other and elbows near your sides, avoid rocking back.', 'Step:5 Keep the palms facing each other and the wrists straight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
  'https://static.exercisedb.dev/media/2NpxjC1.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
