  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Stand tall with a dumbbell in each hand, palms facing forward.', 'Step:2 Let the elbows do the moving while the upper arms stay put and curl the dumbbells as high as possible while contracting your biceps.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
