  'dumbbell incline alternate press',
  'chest',
  'dumbbell',
  'pectorals',
  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Take a seat on an incline bench with a dumbbell in each hand, resting on your thighs.', 'Step:2 Recline on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Lower the weight to its starting height under control before pressing again, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/TVdivgY.gif',
