  ARRAY['forearms']::text[],
  ARRAY['Step:1 Stand tall with a dumbbell in each hand, palms facing down and arms straight.', 'Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Step:5 Keep the palms in the chosen grip without bending the wrists back.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
