  ARRAY['Step:1 Take a seat on a preacher curl bench with your feet planted.', 'Step:2 Take a dumbbell in one hand with palms facing up, resting your upper arm against the preacher pad.', 'Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Step:4 Curl the weight while your upper arms stay in contact with the pad.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
