(
  '9a2c1823-11a4-59a5-b082-aad660ee1d69',
  'dumbbell rotations shoulder',
  'Dumbbell Shoulder Rotations',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.', '1. **External Rotation**: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.', '2. **Internal Rotation**: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.']::text[],
  null,
  null,
