  'abdominals',
  ARRAY['obliques']::text[],
  ARRAY['Step:1 Stand tall with your feet about shoulder width and hold a dumbbell in one hand, letting it hang down by your side.', 'Step:2 With your back straight and your core engaged, With control bend sideways at the waist toward the opposite side of the dumbbell, lowering the weight as far as you comfortably can.', 'Step:3 Stand or sit tall with the pelvis facing forward.', 'Step:4 Bend sideways through the waist without twisting or letting the hips shift.', 'Step:5 Let the side of the trunk work, do not twist or shift the hips.', 'Step:6 Bring the weight or body back to its starting position without rushing.']::text[],
