  'glutes',
  ARRAY['hamstrings', 'erector spinae']::text[],
  ARRAY['Step:1 Stand and set your feet about hip width, holding a dumbbell in your right hand.', 'Step:2 Transfer your weight onto your left leg and lift your right foot slightly off the ground.', 'Step:3 Unlock the knees and brace the abdomen before moving the hips back.', 'Step:4 Push the hips back while keeping the load close and the spine steady.', 'Step:5 Keep the weight close to the legs and stop when the back would begin to round.', 'Step:6 Drive the hips forward to stand tall without leaning back at the top.']::text[],
