  ARRAY['Step:1 Take a seat on a bench or chair with your feet planted.', 'Step:2 Take a dumbbell in one hand with palms facing up, resting your forearm on your thigh.', 'Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Step:4 Move through the wrists or fingers while the forearms stay supported and still.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Ease back to the start without letting the load fall from your hands, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/q8aHNoF.gif',
