(
  '4154321d-7a08-5655-bb00-48e5d29d6d8a',
  'curl dumbbell preacher singlearm zottman',
  'Dumbbell Single-Arm Zottman Preacher Curl',
  'biceps',
  'dumbbell',
  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Take a seat on a preacher curl bench and hold a dumbbell in one hand with palms facing up.', 'Step:2 Set your upper arm on the preacher bench pad, letting your arm to fully extend.', 'Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Step:4 Curl palms-up, turn the palms down at the top, and lower with that overhand grip.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/sxY5Biu.gif',
