  'dumbbell',
  'pectorals',
  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Take a seat on an exercise ball with a dumbbell in each hand, palms facing each other.', 'Step:2 Set one foot on the ground and extend the other leg straight out in front of you.', 'Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.', 'Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Step:5 Keep the pelvis level as the supporting leg does the work.', 'Step:6 Open the arms back along the same arc without dropping the load, switch sides when the set calls for it.']::text[],
