(
  'a3cb0465-037f-57a8-bfad-f5d344954508',
  'dumbbell snatch',
  'dumbbell snatch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Key Steps to Execute Correctly:', 'Setup: Place the dumbbell between your feet, with your shoulders above your hips, chest up, and back flat.', 'The Pull: Explosively extend your hips, knees, and ankles (triple extension) to drive the dumbbell upward, keeping your elbow high and the dumbbell close to your body.', 'The Catch: Quickly flex your hips and knees to drop under the dumbbell and receive it overhead with your arm locked in position, landing in a half-squat stance.', 'Common Mistakes: Using your arms too much to lift the weight instead of your legs, having a low elbow during the pull phase, and misaligning your shoulder, elbow, and wrist in the final position. For beginners, it’s recommended to start with light loads, focus on technique, and perform 3 to 5 sets of 3 to 5 reps per arm.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Aleid'
),
(
  '820c4040-890a-530e-84cd-f95414d7c48a',
