  ARRAY['Step:1 Take your place in front of a step or platform with a dumbbell in each hand, palms facing your body.', 'Step:2 Set your right foot on the step, ensuring your entire foot is in contact with the surface.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
