(
  'd05890f3-b6f5-5160-80ca-8f3a5aabc777',
  'dumbbell step ups',
  'Dumbbell Step Ups',
  'legs',
  'dumbbell',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Step_Ups/0.jpg',
