  ARRAY['hamstrings', 'erector spinae']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.', 'Step:2 With your back straight and your core engaged, hinge at the hips and lower the dumbbells toward the ground, letting a slight bend in your knees.', 'Step:3 Unlock the knees and brace the abdomen before moving the hips back.', 'Step:4 Push the hips back while keeping the load close and the spine steady.', 'Step:5 Keep the weight close to the legs and stop when the back would begin to round.', 'Step:6 Drive the hips forward to stand tall without leaning back at the top.']::text[],
