(
  'ed94939e-cb64-57b1-977d-01961e6882e9',
  'dead dumbbell row undergrip',
  'Dumbbell Underhand Dead Row',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.', '1. Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.', '2. Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.', '3. Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.', '4. Slowly lower to the starting position and repeat. Keep your back flat all the time.']::text[],
