  'upper back',
  ARRAY['triceps', 'deltoids']::text[],
  ARRAY['Step:1 Begin by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.', 'Step:2 Brace your trunk and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
