),
(
  '1e67ddf0-d0c3-5e66-959d-1c830dcf2404',
  'cable elevated row',
  'Elevated Cable Rows',
  'back',
  'cable',
  'lats',
  ARRAY['middle back', 'traps']::text[],
  ARRAY['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.', 'Place it on the seat of the cable row machine.', 'Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elevated_Cable_Rows/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '34f49301-524c-509b-8af9-4427ccb048ac',
  'elevated hamstring stretch',
  'Elevated Hamstring Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Stand facing a bar, box or bench at roughly hip height and place the heel of one leg on it. Keep that leg straight with the toes pointing up, and keep the standing leg straight with both hips square to the support.', 'Hinge forward at the hips with a flat back until you feel a stretch in the back of the elevated thigh. Hold the position while breathing calmly, then switch legs.', 'Stretch for the hamstrings. The height of the support controls the intensity: the higher the leg, the stronger the stretch.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
(
  'dd2f25f6-d4d4-5bcd-8b71-3cf3975093d1',
  'elevated prayer stretch',
  'Elevated prayer stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Starting position:**', 'Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up.', '**Steps:**', '1. On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench.', '2. Hold for a few seconds.', '3. On inhale, relax your back to return to the starting position.', '4. 4. Repeat.']::text[],
  null,
  null,
  'wger',
