  'latissimus dorsi',
  ARRAY['deltoids', 'core']::text[],
  ARRAY['Step:1 Take a seat on the stability ball with your feet planted and your back straight.', 'Step:2 Take a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.', 'Step:3 Start with a manageable load and a small bend in the elbows.', 'Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Lower the arms slowly to your sides without swinging the weight, switch sides when the set calls for it.']::text[],
