  'legs',
  'dumbbell',
  'calves',
  ARRAY['hamstrings', 'quadriceps']::text[],
  ARRAY['Step:1 Stand and set your back against a wall and place an exercise ball between your lower back and the wall.', 'Step:2 Set your feet about shoulder width, with your toes pointing forward.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Lower the heels at a measured pace before rising again.']::text[],
  'https://static.exercisedb.dev/media/xo6sENf.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
