  'chest',
  'stability ball',
  'pectorals',
  ARRAY['deltoids', 'triceps', 'core']::text[],
  ARRAY['Step:1 Begin in a push-up position with your hands on the floor and your shins resting on the stability ball.', 'Step:2 Brace your trunk and lift your hips up toward the ceiling, rolling the ball toward your hands.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
