  'Exercise Ball Prsingle-Leg Raise',
  'back',
  'stability ball',
  'erector spinae',
  ARRAY['abdominals', 'glutes']::text[],
  ARRAY['Step:1 Position yourself face down on a mat with your legs extended and your toes resting on top of the stability ball.', 'Step:2 Set your hands on the ground, about shoulder width, and Brace your trunk muscles.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Keep the pelvis level as the supporting leg does the work.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/lCKm4Rs.gif',
