  ARRAY['hamstrings', 'quadriceps', 'core']::text[],
  ARRAY['Step:1 Position yourself face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.', 'Step:2 Set your hands on the ground in front of you for support.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the pelvis level as the supporting leg does the work.', 'Step:6 Return through center before turning to the other side, switch sides when the set calls for it.']::text[],
