(
  '99f9e59f-54b9-58c8-a7dd-f57aeb7f670c',
  'external rotation',
  'External Rotation',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.', 'Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '3e2ec5b5-a3b1-5de2-b37c-8ece8e0f93b1',
  'external rotation stretch',
  'External Rotation Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.', '2. Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.', '3. Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.', '4. Lower your hand to the original position and repeat.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Croak6728'
),
(
  '193b2c26-d659-5c31-8f2f-60c13e9cdb85',
  'band external rotation',
  'External Rotation with Band',
  'shoulders',
  'bands',
  'shoulders',
  '{}'::text[],
  ARRAY['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation_with_Band/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
