  ARRAY['Step:1 Stand tall with a dumbbell in each hand, palms facing your sides.', 'Step:2 Keep your spine in a comfortable neutral position and your shoulders back.', 'Step:3 Stand tall with the load secure and the shoulders level.', 'Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.', 'Step:5 Keep steps even and avoid leaning away from the load.', 'Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk.']::text[],
