  ARRAY['wrist flexors', 'grip muscles']::text[],
  ARRAY['Step:1 Plant both feet while seated on a bench, hold a barbell with palms facing up.', 'Step:2 Set your forearms on your thighs, letting your wrists hang off the edge.', 'Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Step:4 Let the bar roll toward your fingertips, then close your fingers firmly around it.', 'Step:5 Use a small, smooth range without swinging the elbows.', 'Step:6 Ease back to the start without letting the load fall from your hands.']::text[],
