(
  '0ce0441d-0ccd-556b-bf9d-1c6ff93d9e01',
  'finger pushup',
  'Finger Pushup',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Hand Positioning:', '- Start in a plank position with your hands directly beneath your shoulders.', '- Spread your fingers wide apart, placing them firmly on the ground.', '2. Finger Placement:', '- Gradually lift your palms off the ground, shifting the weight onto your fingers.', '- Focus on distributing the load evenly across your fingertips and thumbs.', '3. Body Alignment:', '- Maintain a straight line from head to heels to engage your core.', '- Keep your body in a controlled and stable position throughout the exercise.', '4. Lowering Phase:', '- Slowly bend your elbows, lowering your chest towards the ground.', '- Ensure controlled movement, maintaining stability on your fingertips.', '5. Pushing Up:', '- Press through your fingertips to straighten your arms, returning to the starting position.', '- Emphasize the engagement of your fingers and thumbs throughout the push-up.']::text[],
