  ARRAY['obliques', 'deltoids']::text[],
  ARRAY['Step:1 Begin by gripping a vertical pole with both hands, palms facing each other, and arms straight.', 'Step:2 Brace your trunk and lift your legs off the ground, keeping them straight.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
