(
  '83452d8b-4353-57d7-81da-05f25bd8f02f',
  'machine press',
  'Flat Machine Press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['### **Execution**', '1. **Start position:**', '* Elbows bent at roughly 90°, hands just outside your chest.', '* Keep wrists straight and aligned with your forearms.', '2. **Pressing phase (concentric):**', '* Push the handles forward until your arms are **almost fully extended** — don’t lock out.', '* Focus on **squeezing your chest** at the end of the movement.', '3. **Returning phase (eccentric):**', '* Slowly bring the handles back toward your chest, feeling the **stretch in your pecs**.', '* Maintain tension — don’t let the weight stack touch down between reps.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'daiben'
),
(
  'ae49391a-6890-554e-9d0b-0940951e6e13',
  'flexbar twist tyler',
  'FlexBar Tyler Twist',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['An eccentric exercise for the wrist extensors, done with a flexible resistance bar such as a Theraband FlexBar, and widely used in rehabilitation for lateral epicondylitis (tennis elbow). Hold the bar vertically in the affected hand with the wrist extended. Grasp the top of the bar with the other hand, palm facing away, and twist the top hand to wind up the bar. Bring both arms out in front of you with the bar horizontal, then slowly let the affected wrist untwist the bar over about four seconds while the other hand holds steady. Reset and repeat. The reverse version, twisting in the opposite direction for the wrist flexors, is used for medial epicondylitis (golfer''s elbow). Move slowly and stop if the exercise causes sharp pain rather than the expected mild discomfort.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
(
  'a6045005-6d17-5bf8-8efc-780d8dc4f413',
  'extension flexbar wrist',
  'FlexBar Wrist Extension',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Performed with a flexible resistance bar such as a Theraband FlexBar. Rest your forearm on your thigh or a table with the palm facing down and the wrist just past the edge. Hold the bar in that hand, let the wrist drop, then extend the wrist to raise the bar, keeping the forearm still. Lower slowly, taking about three seconds. The resistance comes from twisting or bending the flexible bar, so a thicker or stiffer bar increases the load. Commonly used for wrist and forearm strengthening and for elbow tendon rehabilitation.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
