  '{}'::text[],
  ARRAY['Performed with a flexible resistance bar such as a Theraband FlexBar. Rest your forearm on your thigh or a table with the palm facing up and the wrist just past the edge. Hold the bar in that hand, let the wrist extend back, then curl the wrist up to raise the bar while the forearm stays still. Lower slowly, taking about three seconds. Works the wrist flexors, and is the companion movement to FlexBar wrist extension for balanced forearm strengthening.']::text[],
