  'biceps',
  '{}'::text[],
  ARRAY['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.', 'Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.', 'Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.', 'Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.', 'As you inhale, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flexor_Incline_Dumbbell_Curls/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9b39561f-236d-5c14-9125-aabd59cdd234',
  'dips floor',
  'Floor dips',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Sit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together.', 'Steps:', '1. Raise your hips off the ground, straightening your arms.', '2. Bend your elbows, bringing your hips down.', '3. Straighten your arms, returning to the previous position.', '4. Repeat steps 2 and 3.', 'Notes:', 'The exercise''s difficulty depends on how high you bring your hips.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
(
