  'floor fly (with barbell)',
  'chest',
  'barbell',
  'pectorals',
  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Settle onto your back on the floor with your knees bent and feet planted.', 'Step:2 Take a barbell with palms facing down, arms extended straight up over your chest.', 'Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.', 'Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Step:5 Keep the elbow angle nearly unchanged through the arc.', 'Step:6 Open the arms back along the same arc without dropping the load.']::text[],
  'https://static.exercisedb.dev/media/neonEDL.gif',
