  'floor glute ham raise',
  'Floor Glute-Ham Raise',
  'legs',
  '',
  'hamstrings',
  ARRAY['calves', 'glutes']::text[],
  ARRAY['You can use a partner for this exercise or brace your feet under something stable.', 'Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.', 'Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.', 'Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.']::text[],
