  ARRAY['Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.', 'Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.']::text[],
