  'legs',
  'bodyweight',
  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about hip width and hands on your hips.', 'Step:2 Step wide forward with your right foot, lowering your body into a lunge position.', 'Step:3 Set your stance wide enough to balance before bending either knee.', 'Step:4 Step into the movement and bend both knees, keeping your front foot planted.', 'Step:5 Keep the front foot planted and avoid collapsing inward at the knee.', 'Step:6 Push through the lead foot to return to the start, then change legs as planned.']::text[],
