(
  '48664148-dabc-550a-9fa0-8966aaa34e9d',
  'frankenstein squat',
  'frankenstein squat',
  'legs',
  'barbell',
  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and hold the barbell ahead of your body with straight arms.', 'Step:2 With your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
