(
  'ba757835-1884-5973-bc0f-8b8caa605e0b',
  'freehand jump squat',
  'Freehand Jump Squat',
  'legs',
  'body only',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Cross your arms over your chest.', 'With your head up and your back straight, position your feet at shoulder width.', 'Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.', 'Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.', 'When you touch the floor again, immediately squat down and jump again.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Freehand_Jump_Squat/0.jpg',
  'image',
