  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Settle onto your back with your knees bent and feet planted.', 'Step:2 Set your hands behind your head with your elbows pointing outwards.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Bring the soles of your feet together, let the knees open, then curl your ribs toward your pelvis.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
