  'frog planche',
  'frog planche',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['deltoids', 'pectorals', 'triceps']::text[],
  ARRAY['Step:1 Set a straight-arm plank with the hands below the shoulders and the feet together.', 'Step:2 Bend your elbows and lower your body toward the ground, with your spine steady.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
