(
  'e839a926-d14f-5944-99eb-efa224e24c21',
  'frog sit ups',
  'Frog Sit-Ups',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.', 'Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.', 'Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.', 'Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.', 'As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.', 'As you inhale, slowly lower back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Sit-Ups/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '63fd00b4-5ce6-52e6-916c-400bef91d47d',
  'frog stand',
  'Frog stand',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Starting position:**', '- Stand with your feet shoulder-width apart and your toes pointing forward, facing a wall or bench for support if needed.', '- Bend your knees into a squat position.', '- Place your hands on the ground in front of you, shoulder-width apart, with your fingers spread wide.', '- Make sure your elbows are under your shoulders and your body forms a straight line from your head to your heels.', '**Upward phase:**', '- Push with your feet and hands to lift your body off the ground.', '- Straighten your legs and arms, keeping your body aligned.', '- Engage your core and glutes to maintain the position.', '- If needed, rest your knees on the wall or bench for assistance.']::text[],
  null,
  null,
  'wger',
