(
  '9206bbd5-8a98-5210-839b-98accef3429f',
  'box front jump',
  'Front Box Jump',
  'legs',
  'other',
  'hamstrings',
  ARRAY['abductors', 'adductors', 'calves', 'glutes', 'quadriceps']::text[],
  ARRAY['Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.', 'Perform a short squat in preparation for jumping, swinging your arms behind you.', 'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.', 'Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.']::text[],
