  ARRAY['Step:1 Begin by hanging from a pull-up bar with palms facing down, hands about shoulder width.', 'Step:2 Brace your trunk and pull your shoulder blades down and back.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
