(
  '70a64211-90da-5a44-804a-eeb5eb35db3f',
  'front plank',
  'Front Plank',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism.', 'Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body.', 'Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hektkaso'
),
(
  'fbf46ef4-c198-55be-b958-8ba5f3fd633a',
  'front plank twist',
  'front plank with twist',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['obliques', 'deltoids']::text[],
  ARRAY['Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.', 'Step:2 Brace your trunk and glutes to maintain a stable position.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
  'https://static.exercisedb.dev/media/CosupLu.gif',
