(
  'd8b0df01-d4fa-5936-8a1b-cfb26ac3c676',
  'front pullover raise',
  'Front Raise And Pullover',
  'chest',
  'barbell',
  'chest',
  ARRAY['lats', 'shoulders', 'triceps']::text[],
  ARRAY['Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.', 'Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.', 'Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.', 'Now return the barbell to the starting position by reversing the motion as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Raise_And_Pullover/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'e502b926-d6f5-5967-87ec-ba44ed968449',
  'front raise',
  'Front Raises',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip.', 'The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight.', 'When lifting it is important to keep the body still so the anterior deltoid is fully utilised, if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury.', 'A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Manu, wikipedia'
),
(
  'd2ad8f03-a1ae-59e3-8aea-6c04b7d9c976',
  'front plates raise',
  'Front Raises with Plates',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit.', '1. While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. **Tip**: The arms will remain in this position throughout the exercise. This will be your starting position.', '2. Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position.', '3. Repeat for the recommended amount of repetitions.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Marius'
),
(
  '905f7319-1683-56e7-bd71-f023a8ddc553',
  'front split stretch',
  'Front Split Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Start kneeling.', '2. Extend one leg out forwards, fully straightened. Follow with your hips so your back leg begins to unfold.', '3. Carefully lower yourself into the stretch. Do not go beyond your limit.', '4. Hold for the required time.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Croak6728'
),
(
  '2d2db445-02fe-5dc7-93c5-511d813e1a38',
  'clean front squat',
  'Front Squat (Clean Grip)',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['abdominals', 'glutes', 'hamstrings']::text[],
  ARRAY['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.', 'Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Squat_Clean_Grip/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
