  ARRAY['Step:1 Begin by standing with your feet about shoulder width and your arms extended straight out to the sides.', 'Step:2 With control lean forward, keeping your arms straight, until your upper body is parallel to the ground.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
