  ARRAY['Step:1 Place your palms near the hips and lean forward until the shoulders pass the wrists.', 'Step:2 Lift both feet clear of the floor with straight legs and a firm trunk.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
