(
  '2c4e4982-9534-5da2-a22f-a167282e7d42',
  'lat motion pulldown range',
  'Full Range-Of-Motion Lat Pulldown',
  'back',
  'cable',
  'lats',
  ARRAY['biceps', 'middle back', 'shoulders']::text[],
  ARRAY['Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.', 'Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.']::text[],
