(
  'dc836cfc-b1e7-5685-9234-f2994d70ff56',
  'chinup gironda sternum',
  'Gironda Sternum Chin-Up',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['biceps', 'rhomboids', 'rear deltoids']::text[],
  ARRAY['Step:1 Face the high bar from a stable stance with feet about shoulder width.', 'Step:2 Reach up to hold the bar with palms facing down, just beyond shoulder width.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Lean back as you pull, aiming the sternum toward the bar and drawing your elbows behind you.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
