  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'c4b25590-1cb9-59cc-bdee-ba633ef19054',
  'chins gironda sternum',
  'Gironda Sternum Chins',
  'back',
  'other',
  'lats',
  ARRAY['biceps', 'middle back']::text[],
  ARRAY['Grasp the pull-up bar with a shoulder width underhand grip.', 'Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.', 'Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.', 'Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement, your head will be parallel to the floor.', 'Slowly start going back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gironda_Sternum_Chins/0.jpg',
