(
  '51a73d2e-c9b4-560c-be82-4d3b6609497f',
  'bridge glute',
  'Glute Bridge',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'tdprice12'
),
(
  'e062f158-a82a-592b-8607-956a5742def4',
  'bridge glute march',
  'glute bridge march',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings', 'quadriceps']::text[],
  ARRAY['Step:1 Settle onto your back with your knees bent and feet planted.', 'Step:2 Tighten your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.', 'Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Step:4 Press through the feet and lift your hips until your torso and thighs line up.', 'Step:5 Stop when the hips line up with the torso, do not arch higher through the lower back.', 'Step:6 Lower the hips steadily and keep the feet planted for the next lift.']::text[],
  'https://static.exercisedb.dev/media/GibBPPg.gif',
