  'hamstrings',
  ARRAY['glutes', 'erector spinae']::text[],
  ARRAY['Step:1 Set the glute-ham raise machine to fit your body.', 'Step:2 Set yourself face down on the machine with your ankles secured.', 'Step:3 Line the knees up with the machine or bench edge before starting the curl.', 'Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Step:5 Keep the hips still while the knees bend.', 'Step:6 Return along the same path at a controlled pace.']::text[],
