(
  '209b365b-c658-5b64-bb6c-26cf5d68db86',
  'good morning',
  'Good Morning',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['abdominals', 'glutes', 'lower back']::text[],
  ARRAY['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '8ee3b304-3b22-52fb-90fd-007fb53f06ce',
  'good morning off pins',
  'Good Morning off Pins',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['abdominals', 'glutes', 'lower back']::text[],
  ARRAY['Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning_off_Pins/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'f64b57c0-6d1b-51c8-964a-a9a19517fc96',
  'chin gorilla',
  'gorilla chin',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['forearms', 'biceps']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your knees soft.', 'Step:2 Hold a pull-up bar with palms facing down, just beyond shoulder width.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
  'https://static.exercisedb.dev/media/bmwlYvD.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '941b673f-1ca0-59ca-a747-c95ade463409',
  'chin crunch gorilla',
  'Gorilla Chin/Crunch',
  'core',
  'body only',
  'abdominals',
  ARRAY['biceps', 'lats']::text[],
  ARRAY['Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.', 'Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.', 'As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.', 'Slowly start to inhale as you return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gorilla_Chin_Crunch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
