(
  '67aa4452-7bc5-5c97-9441-a8a36c68f931',
  'calf hack raise',
  'hack calf raise',
  'legs',
  'sled machine',
  'calves',
  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Set the sled machine to a comfortable weight.', 'Step:2 Step onto the sled machine with your toes on the platform and your heels hanging off.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Pause at the top without rolling the ankles outward.', 'Step:6 Lower the heels at a measured pace before rising again.']::text[],
  'https://static.exercisedb.dev/media/2ORFMoR.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
