(
  'a6eb7196-e021-5aa9-9724-feb8a97bf2fc',
  'calf hack raise singleleg',
  'Hack Single-Leg Calf Raise',
  'legs',
  'sled machine',
  'calves',
  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Set the sled machine to an appropriate weight.', 'Step:2 Step onto the sled machine with one foot, keeping the other foot off the ground.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Keep the pelvis level as the supporting leg does the work.', 'Step:6 Lower the heels at a measured pace before rising again, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/AxFoqAD.gif',
