(
  '52caac2a-e85c-5e1f-bc67-9051505e7ba6',
  'curl hammer',
  'Hammer Curls',
  'biceps',
  'dumbbell',
  'biceps',
  '{}'::text[],
  ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '8d5a95b7-7e72-5ffd-af55-8e0147aa04a3',
  'bench dumbbell hammer incline press',
  'Hammer Grip Incline DB Bench Press',
  'chest',
  'dumbbell',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Grip_Incline_DB_Bench_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'dc9b2826-c6b1-5873-b2ee-1c27b34b9e2a',
  'cable hammercurls',
  'Hammercurls on Cable',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms.', 'Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move.']::text[],
