(
  '79056275-b8b1-5013-b109-614e0714324e',
  'chest decline hammerstrength press',
  'Hammerstrength Decline Chest Press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Sit upright in a hammerstrength decline chest press machine while squeezing your shoulder blades together and placing your heels firmly on the ground underneath your knees.', '2. The back pad should be contact with your head, shoulders, and butt at all times.', '3. Grab ahold of the handles with an overhand grip just outside shoulder-width apart just below your chest.', '4. Keeping your core braced by breathing into your stomach and flexing the abdominal muscles, push through your palms to extend your elbows while keeping them at a 45 degree angle from your torso.', '5. Once your arms are fully extended, return to the starting position.']::text[],
