  'bodyweight',
  'hamstrings',
  ARRAY['glutes']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width.', 'Step:2 Move forward with your right foot and shift your weight onto your right leg.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
