  'pectorals',
  ARRAY['triceps', 'deltoids']::text[],
  ARRAY['Step:1 Set the seat height and handlebar position to a comfortable level.', 'Step:2 Take a seat on the ergometer with your back straight and feet on the pedals.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
  'https://static.exercisedb.dev/media/pAIWRGu.gif',
