(
  'a65cc66d-e689-5218-ad8c-d3d3ad071c10',
  'circular clasped toe touch',
  'Hands Clasped Circular Toe Touch',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings', 'quadriceps', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your hands clasped together ahead of your chest.', 'Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Step:3 Soften the knees and let the hips start the fold.', 'Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Step:5 Keep the movement controlled throughout the range.', 'Step:6 Hold briefly at a comfortable depth, then rise by extending the hips.']::text[],
  'https://static.exercisedb.dev/media/B5xca8s.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'b57429e4-c369-526e-ae89-7c945953cf34',
  'circular clasped reversed toe touch',
  'Hands Reversed Clasped Circular Toe Touch',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings', 'quadriceps', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your arms extended to the sides.', 'Step:2 Bend forward at the waist, with your spine steady and your knees soft.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold briefly at a comfortable depth, then rise by extending the hips.']::text[],
  'https://static.exercisedb.dev/media/yq3GAJX.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
