  ARRAY['Step:1 Choose an open space with enough room to perform a handstand.', 'Step:2 Set your hands on the ground about shoulder width, fingers pointing forward.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
  'https://static.exercisedb.dev/media/XooAdhl.gif',
