  ARRAY['Step:1 Choose a wall and face away from it, standing a few feet away.', 'Step:2 Set your hands on the ground about shoulder width and kick your feet up against the wall, coming into a handstand position.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
