(
  '3103ca63-2963-5f76-94d5-9bc1ccc4056b',
  'clean hang',
  'Hang Clean',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps']::text[],
  ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '4931019e-b50c-510a-be11-cbe6c0473aa6',
  'below clean hang knees',
  'Hang Clean - Below the Knees',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps']::text[],
  ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.', 'At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean_-_Below_the_Knees/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd2e340bd-3e69-505f-9319-bb02cecb1939',
  'hang snatch',
  'Hang Snatch',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['abdominals', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[],
  ARRAY['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '76f4670d-8664-56a0-8a9b-621d5e32b11d',
  'below hang knees snatch',
  'Hang Snatch - Below Knees',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['abdominals', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[],
  ARRAY['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead, and then return the weight to the floor under control.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch_-_Below_Knees/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'e98f5f7a-7d67-5d2d-821d-425316e06216',
  'bar good hanging morning',
  'Hanging Bar Good Morning',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['abdominals', 'glutes', 'lower back']::text[],
  ARRAY['Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.', 'Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.', 'Slowly lower the weight back to the starting position, where it is supported by the chains.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Bar_Good_Morning/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c35efed4-0c2c-59f8-9f21-8b49352b59f2',
  'hanging hip leg raise',
  'hanging leg hip raise',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors', 'erector spinae']::text[],
  ARRAY['Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Step:2 Brace your trunk and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.', 'Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Step:4 Press through the feet and lift your hips until your torso and thighs line up.', 'Step:5 Stop when the hips line up with the torso, do not arch higher through the lower back.', 'Step:6 Lower the hips steadily and keep the feet planted for the next lift.']::text[],
  'https://static.exercisedb.dev/media/VEcJRo2.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
