  ARRAY['Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Step:2 Brace your trunk and lift your legs up in front of you, keeping them straight.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position.']::text[],
