  'chest',
  'other',
  'chest',
  ARRAY['abdominals', 'shoulders', 'triceps']::text[],
  ARRAY['Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.', 'Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.', 'Receive the bag as it swings back by reversing these steps.']::text[],
