(
  'd83ab4c2-99b6-54e3-8831-054152e38ff3',
  'heel touches',
  'Heel Touches',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['- **Starting Position:**', '* Lie on your back on an exercise mat.', '* Bend your knees, keeping your feet flat on the floor and hip-width apart.', '* Place your arms along your sides, palms facing inward, just off the floor.', '- **Engage Core:**', '* Lift your head, shoulders, and upper back slightly off the ground.', '* Keep your neck neutral and chin slightly tucked.', '- **Perform the Movement:**', '* Side-bend to the right, reaching your right hand toward your right heel.', '* Return to the center, then side-bend to the left, reaching your left hand toward your left heel.', '* Continue alternating sides in a controlled manner.', '- **Breathing:**', '* Exhale as you reach toward your heel and inhale as you return to the center.']::text[],
