  '',
  '',
  '{}'::text[],
  ARRAY['Setup: Place your chest on the end of a bench, using a towel or anything soft to keep your chest protected. You want your chest to be in contact with the bench around the nipple line. Your back should be almost parallel to the floor', 'Execution: When you’re starting the exercise, focus on pulling your elbows back until you feel maximum tightness in the lats.', 'If you want to get some trap activation with the exercise, relax your shoulder blades when the weights are hanging down and then retract them as you start the rep.']::text[],
