  '210dbcc8-ab78-55ea-961b-ddacf0a609d9',
  'cable curl high',
  'High Cable Curls',
  'biceps',
  'cable',
  'biceps',
  '{}'::text[],
  ARRAY['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.', 'Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.', 'Slowly bring back the arms to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
