(
  '84a374b1-237d-5b9a-a1f1-e8656084ebaa',
  'hinge hip',
  'Hip hinge',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Hip Hinge Exercise Description', 'The hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge:', '1. **Starting Position:** Stand with your feet hip-width apart and a slight bend in your knees.', '2. **Hinge at the Hips:** Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up.', '3. **Lowering Phase:** Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings.', '4. **Return to Standing:** Drive through your heels and thrust your hips forward to return to the starting position.']::text[],
  null,
  null,
