(
  '78ffed69-f6d6-5059-a637-7115e0a749c4',
  'hip lateral out steps',
  'Hip-Out and Hip-In Lateral Steps',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['# Overview of Hip-Out and Hip-In Lateral Steps', 'Hip-out and hip-in lateral steps are effective exercises designed to strengthen the hip abductors and enhance lateral stability. These movements are beneficial for improving coordination and overall hip function.', '## Exercise Descriptions', '### Hip-Out Steps', '- **Movement:** Step out to the side with one leg, keeping the other leg stable.', '- **Target Muscles:** Primarily engages the hip abductors, including the gluteus medius and minimus.', '- **Benefits:** Increases lateral stability and strength in the hip area.', '### Hip-In Steps', '- **Movement:** Bring the leg back in toward the center after stepping out.', '- **Target Muscles:** Continues to engage the hip abductors while also activating the adductors.', '- **Benefits:** Enhances coordination and control of the hip joint.', '## Key Benefits of Lateral Steps', '| Benefit | Description |', '|---|---|', '| **Strengthening Hip Abductors** | Improves muscle strength around the hip joint. |', '| **Enhancing Stability** | Increases lateral stability, reducing the risk of falls. |', '| **Improving Coordination** | Develops better control and movement patterns in the hips. |', 'Incorporating hip-out and hip-in lateral steps into a regular exercise routine can lead to improved hip strength and stability, which is essential for various physical activities and daily movements.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'aboksz'
),
