  ARRAY['Step:1 Begin by standing with your feet about shoulder width.', 'Step:2 Before moving, bend your knees and lower your body down into a squat position.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
