  'erector spinae',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Step:1 Set the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.', 'Step:2 Fold your arms over your chest or place your hands behind your head.', 'Step:3 Secure the hips and feet on the support before lifting.', 'Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Step:5 Finish in a straight body line, before the lower back overarches.', 'Step:6 Bring the weight or body back to its starting position without rushing.']::text[],
