  'b33283a9-53e0-599a-bfd3-72115a613d2d',
  'hyperextensions',
  'Hyperextensions',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you''re horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles.']::text[],
