  'triceps',
  ARRAY['pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Set yourself between two parallel bars with your arms straight and your body suspended in the air.', 'Step:2 Before moving, bend your knees and cross your ankles.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
  'https://static.exercisedb.dev/media/05Cf2v8.gif',
