(
  '2dcb5e8b-fb54-58f6-9466-45c7205e3493',
  'inchworm',
  'inchworm',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['deltoids', 'hamstrings']::text[],
  ARRAY['Step:1 Begin in a standing position with your feet about hip width.', 'Step:2 Before moving, bend forward at the waist and place your hands on the ground in front of you.', 'Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Step:4 Reach the arms away while keeping your ribs and pelvis aligned, stop before the lower back sags.', 'Step:5 Stop reaching when the lower back starts to sag.', 'Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[],
  'https://static.exercisedb.dev/media/TV87DNB.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '5ab46ad2-ce0b-5855-b95e-54d48fa4571a',
  'barbell extension incline triceps',
  'Incline Barbell Triceps Extension',
  'triceps',
  'barbell',
  'triceps',
  ARRAY['forearms']::text[],
  ARRAY['Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.', 'Lie back on an incline bench set at any angle between 45-75-degrees.', 'Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.', 'Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.', 'Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Barbell_Triceps_Extension/0.jpg',
  'image',
