(
  'd537e6ca-7ac9-5e3e-936a-09927a8c4895',
  'bench incline pull',
  'Incline Bench Pull',
  'back',
  'barbell',
  'middle back',
  ARRAY['lats', 'shoulders']::text[],
  ARRAY['Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.', 'Let the arms hang to your sides fully extended as they point to the floor.', 'Turn the wrists until your hands have a pronated (palms down) grip.', 'Now flare the elbows out. This will be your starting position.', 'As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter "T" at the top of the movement. Hold the contraction at the top for a second.', 'Slowly go back down to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Bench_Pull/0.jpg',
