(
  'a9e503c4-a7d4-54ba-8374-9e0336ca9a29',
  'cable chest incline press',
  'Incline Cable Chest Press',
  'chest',
  'cable',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to the starting position, keeping tension on the cables.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Chest_Press/0.jpg',
  'image',
