),
(
  'df574530-0dcc-5ebf-9a17-e2c7c31a6c8e',
  'cable flye incline',
  'Incline Cable Flye',
  'chest',
  'cable',
  'chest',
  ARRAY['shoulders']::text[],
  ARRAY['To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).', 'Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.', 'With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.', 'With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Flye/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '208ed9be-1a70-5447-bc0a-d551264b87f9',
  'chest dumbbell incline row supported',
  'Incline Chest-Supported Dumbbell Row',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Set up an adjustable bench at a 45-degree angle.', '2. Lay on your stomach with your head hanging just above the edge of the bench.', '3. Grab a dumbbell in each hand and set up with a good posture – core and lats engaged and shoulders neutral.', '4. Row the dumbbells toward the top of the stomach and squeeze the back at the top of the rep.', '5. Finally, lower the dumbbells back to the starting position and repeat until all reps are completed.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'carlos3c'
),
(
  '976f2004-c9f7-5ed9-8996-c7aac2d89dfe',
  'closegrip incline pushup',
  'incline close-grip push-up',
  'triceps',
  'bodyweight',
  'triceps',
  ARRAY['pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Set your hands close together on a stable raised surface, then walk the feet back into a plank.', 'Step:2 Reach your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
  'https://static.exercisedb.dev/media/1YB40kg.gif',
