(
  '166120bf-5534-58bd-ad3d-0b0153eb4585',
  'biceps curl incline inner',
  'Incline Inner Biceps Curl',
  'biceps',
  'dumbbell',
  'biceps',
  '{}'::text[],
  ARRAY['Hold a dumbbell in each hand and lie back on an incline bench.', 'The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.', 'Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.', 'After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.', 'Repeat for the recommended amount of repetitions.']::text[],
