  ARRAY['Step:1 Choose an elevated surface, such as a bench or step, and place your hands about shoulder width on the edge.', 'Step:2 Move your feet back, keeping your body in a straight line from head to heels.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
