  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['### **Execution**', '1. **Hold Position:**', '* Lower the dumbbells **a few inches above your chest** — about the **midpoint** of a normal incline press.', '* This is where your upper chest is under maximum tension.', '2. **Static Hold:**', '* Hold the position for **20–45 seconds** while keeping the chest tight.', '* Breathe slowly but stay tense — **do not relax your chest or shoulders**.', '3. **End the set:**', '* After the hold, carefully bring the dumbbells down and rest.']::text[],
