  '{}'::text[],
  ARRAY['The **Inverted Lat Pull Down** (most commonly known as the **Reverse Grip Lat Pull Down**) is a variation of the standard exercise that uses an underhand (supinated) grip with hands at shoulder-width. This position shifts more emphasis to the **lower lats** and increases **biceps** involvement, often allowing for a greater range of motion and a deeper squeeze at the bottom of the movement.']::text[],
