(
  'd1b00426-7d59-5a35-945d-16b6102d39b9',
  'chest isometric squeezes',
  'Isometric Chest Squeezes',
  'chest',
  'body only',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).', 'Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Chest_Squeezes/0.jpg',
  'image',
