  'b8589a1a-1a33-527c-8a6b-c4d08bd0de39',
  'back front isometric neck',
  'Isometric Neck Exercise - Front And Back',
  'neck',
  'body only',
  'neck',
  '{}'::text[],
  ARRAY['With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.', 'Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat with your hands placed on the back side of your head.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Neck_Exercise_-_Front_And_Back/0.jpg',
  'image',
  'public_domain',
