  'pectorals',
  ARRAY['deltoids', 'triceps', 'core']::text[],
  ARRAY['Step:1 Begin by lying flat on your back on a mat or bench.', 'Step:2 Reach your arms straight out to the sides, perpendicular to your body.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Keep the trunk braced as the legs move together from side to side.', 'Step:5 Keep the turn smooth instead of throwing the arms across the body.', 'Step:6 Return through center before turning to the other side.']::text[],
