  'cardiovascular system',
  ARRAY['quadriceps', 'hamstrings', 'calves', 'deltoids', 'triceps', 'core']::text[],
  ARRAY['Step:1 Begin in a standing position with your feet about shoulder width.', 'Step:2 Before moving, lower your body into a squat position, placing your hands on the ground in front of you.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
