(
  '8a7edef9-1063-5d3e-9714-6d323497f3ff',
  'jefferson squat',
  'Jefferson Squats',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings', 'lower back', 'traps']::text[],
  ARRAY['Place a barbell on the floor.', 'Stand in the middle of the bar length wise.', 'Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.', 'Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).', 'Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.', 'Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.', 'Now drive yourself back up to the starting position by pushing with the feet . Tip: Keep the bar hanging at arm''s length and your elbows locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your thighs, not your arms.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jefferson_Squats/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '2b8e7355-5b17-5e4d-af32-b4765c67c98f',
  'balance jerk',
  'Jerk Balance',
  'shoulders',
  'barbell',
  'shoulders',
  ARRAY['glutes', 'hamstrings', 'quadriceps', 'triceps']::text[],
  ARRAY['This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.', 'Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.', 'Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Balance/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'fa7c3eca-4811-55cb-85fb-fd727d26a6a9',
  'dip jerk squat',
  'Jerk Dip Squat',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['abdominals', 'calves']::text[],
  ARRAY['This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.', 'Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Dip_Squat/0.jpg',
  'image',
