(
  '43fbf2d3-6863-55a6-8dd8-15bdb52e7a60',
  'jm press',
  'JM Press',
  'triceps',
  'barbell',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.', 'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.', 'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.', 'Now go back to the starting position and start over.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/JM_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
