(
  '16ac378e-266a-5fd3-8a32-ac09b3c9cad7',
  'jogging treadmill',
  'Jogging, Treadmill',
  'legs',
  'machine',
  'quadriceps',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '60ae635d-3504-525a-b70f-f8767153ed81',
  'jump rope',
  'jump rope',
  'cardio',
  'rope',
  'cardiovascular system',
  ARRAY['calves', 'quadriceps', 'hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Take hold of the handles of the jump rope with your hands, palms facing inward.', 'Step:2 Stand and set your feet about shoulder width and knees soft.', 'Step:3 Bend the hips and knees slightly to load the jump.', 'Step:4 Load the legs with a small bend, then drive through the floor and land softly.', 'Step:5 Land with bent hips and knees and let the feet absorb the impact.', 'Step:6 Absorb the landing through the hips and knees before repeating.']::text[],
  'https://static.exercisedb.dev/media/e1e76I2.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'f3ad0a43-8e6d-5cb4-bef3-c0da5c9d7255',
  'jump jumps rope',
  'Jump rope: basic jumps',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Put your feet close together, bend the knees a bit, keep your head and body straight, keep elbows in, open your arms.', 'Steps:', '1. Spin only your wrists with enough force to make the rope spin.', '2. Jump just high enough to pass the rope below your feet.', '3. Repeat.', 'Notes:', 'This exercise requires a jump rope. Make sure the rope length is adjusted to your height. One way to check is to grab both handles with one hand and stand on the middle of the rope hanging on the ground with one foot. If the rope (excluding the handles) reaches just below your chest, its length is right. A shorter rope would be hazardous, as you might hit yourself, and a longer rope would make for bad form.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
(
  '1f551c33-6012-5dc7-b56f-fe576dc6939e',
  'jump squat',
  'jump squat',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width.', 'Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
  'https://static.exercisedb.dev/media/LIlE5Tn.gif',
