  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '10b04eeb-2e4f-5daa-b482-459dbf106cb6',
  'jack jumping',
  'Jumping Jack HD',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Jumping jack are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body.', 'Jumping jack target the arm, shoulder, abdominal muscles, hip muscles and hip flexors and also work on the thighs, knee tendons and quadriceps.', 'Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hektkaso'
),
(
  'dd055f1c-e164-51a6-b11a-bc6158afbc21',
  'jacks jumping',
  'Jumping Jacks',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides']::text[],
