),
(
  '2aa11c57-748a-5a14-9816-58850d78c9dc',
  'keg load',
  'Keg Load',
  'back',
  'other',
  'lower back',
  ARRAY['abdominals', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'shoulders', 'traps']::text[],
  ARRAY['To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.', 'Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.', 'The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.', 'Return to the starting position to retrieve the next keg, and repeat until the event is completed.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Keg_Load/0.jpg',
