),
(
  '27c6ed7a-e77c-5860-931d-a8d3bd39a8bc',
  'kegel',
  'Kegel Exercise',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Lie on your back with your knees bent, or sit upright in a chair. Locate the pelvic floor muscles: they are the muscles you would use to stop the flow of urine or to hold back gas. Keep your abdomen, glutes and thighs relaxed and breathe normally throughout.', 'Tighten the pelvic floor muscles and lift them gently upwards and inwards. Hold the contraction for a few seconds, then release completely and rest for at least as long as you held. Repeat for the desired number of repetitions.', 'The exercise can be varied by holding longer with a light contraction (endurance) or by performing quick, short contractions with a full relaxation in between.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
(
  'ece5d549-b751-5ecc-84f7-671eabd48a40',
  'kelso shrugs',
  'kelso shrugs',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Kelso shrugs are a variation of scapular shrugs designed primarily to train **scapular retraction**, with particular emphasis on the **middle trapezius, rhomboids, and, secondarily, the lower trapezius**. Unlike conventional shrugs, the goal is not to elevate the shoulders toward the ears, but rather to **pull the shoulder blades backward**.', 'They are typically performed with the chest supported on an incline bench, using either dumbbells or a barbell:', '1. Lie face down on an incline bench, with your arms extended toward the floor.', '2. Keep your **elbows almost completely locked** throughout the movement.', '3. Starting with the shoulder blades slightly protracted, **retract them**, trying to bring them closer together.', '4. Keep your chest firmly supported on the bench, avoid turning the movement into a row by extending your torso.', '5. Briefly hold the fully retracted position, then return in a controlled manner, allowing the shoulder blades to separate.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Friend7857'
),
