  ARRAY['deltoids', 'trapezius', 'core']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand with palms facing down.', 'Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.', 'Step:3 Brace before the pull and keep the load close to the body.', 'Step:4 Drive through the legs and hips, then guide the weight to its receiving position.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Stand tall to finish, then lower the weight under control before the next rep, switch sides when the set calls for it.']::text[],
