  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.', 'Step:2 Before moving, press one kettlebell overhead, fully extending your arm.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Lower the weight to its starting height under control before pressing again, switch sides when the set calls for it.']::text[],
