  'hamstrings',
  ARRAY['calves', 'glutes', 'lower back', 'quadriceps', 'traps']::text[],
  ARRAY['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out.']::text[],
