(
  'c2673e11-248b-5016-8ac0-0ef13aafaca7',
  'deadlift kettlebell',
  'Kettlebell deadlifts',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward.', 'Steps:', '1. Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement.', '2. Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart.', '3. While contacting your abs and glutes, stand straight up.', '4. Hinge at the hips again to bring the kettlebell back down, similarly to step 1.', '5. Repeat from step 3.', 'Tips:', '* Be sure you''re performing the movements correctly, as doing otherwise can lead to injury. For example, do not squat instead of hinging at the hips, do not round your back while reaching for the kettlebell, and do not lean back while standing up.']::text[],
  null,
  null,
