  'Kettlebell Halo',
  'shoulders',
  'kettlebells',
  'shoulders',
  ARRAY['traps', 'middle back', 'abdominals', 'triceps']::text[],
  ARRAY['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.', 'Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.', 'Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight.']::text[],
  null,
  null,
  'public_domain',
  'Unlicense',
  null
),
(
  'dc2ae290-69ed-532d-876c-4f5d78938ca9',
  'extension halo kettlebell overhead',
  'Kettlebell Halo with Overhead Extension',
  'shoulders',
  'kettlebells',
  'shoulders',
  ARRAY['traps', 'middle back', 'abdominals']::text[],
  ARRAY['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.', 'From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.', 'Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.', 'Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout, if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises.']::text[],
  null,
  null,
  'public_domain',
  'Unlicense',
  null
),
