  'kettlebell thruster',
  'shoulders',
  'kettlebell',
  'deltoids',
  ARRAY['quadriceps', 'glutes', 'core']::text[],
  ARRAY['Step:1 Begin by standing with your feet about shoulder width, holding a kettlebell ahead of your chest with both hands, palms facing each other.', 'Step:2 Before moving, lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.', 'Step:3 Rack the weight securely and brace before dropping into the squat.', 'Step:4 Stand from the squat and use that leg drive to press the weight overhead.', 'Step:5 Let the leg drive start the press while keeping the ribs from flaring.', 'Step:6 Ease back to the start before repeating.']::text[],
  'https://static.exercisedb.dev/media/yWxMvB5.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'e832c622-6957-5420-a9b3-7c50e3f8128f',
  'get kettlebell lunge turkish up',
  'Kettlebell Turkish Get-Up (Lunge style)',
  'shoulders',
  'kettlebells',
  'shoulders',
  ARRAY['abdominals', 'hamstrings', 'quadriceps', 'triceps']::text[],
  ARRAY['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.', 'Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.', 'While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
