  'get kettlebell squat turkish up',
  'Kettlebell Turkish Get-Up (Squat Style)',
  'legs',
  'kettlebell',
  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'core']::text[],
  ARRAY['Step:1 Begin by lying on your back with your legs extended and the kettlebell held in your right hand, arm straight above your shoulder.', 'Step:2 Before moving, bend your right knee and place your right foot flat on the ground, keeping your left leg extended.', 'Step:3 Fix your gaze on the load and stack the working wrist above its shoulder.', 'Step:4 Move from lying to standing in stages, watching the weight and keeping the supporting arm stacked.', 'Step:5 Move one stage at a time instead of rushing from floor to standing.', 'Step:6 Reverse the same stages to return to the floor, keeping the load steady throughout.']::text[],
  'https://static.exercisedb.dev/media/Ha7SZ3y.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
