  'Kettlebell Two-Arm Clean',
  'shoulders',
  'kettlebell',
  'deltoids',
  ARRAY['trapezius', 'forearms']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a kettlebell ahead of your thighs with both hands, palms facing toward you.', 'Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell toward the ground.', 'Step:3 Brace before the pull and keep the load close to the body.', 'Step:4 Drive through the legs and hips, then guide the weight to its receiving position.', 'Step:5 Receive the load with the torso braced and feet stable.', 'Step:6 Stand tall to finish, then lower the weight under control before the next rep.']::text[],
  'https://static.exercisedb.dev/media/7Ba7bQ2.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
