  'upper back',
  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, knees soft, and hold a kettlebell in each hand with your palms facing your body.', 'Step:2 Bend forward at the hips, with your spine steady and your core engaged.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Bring the elbows back without jerking the torso.', 'Step:6 Reach the arms forward again without letting the torso lurch.']::text[],
