  'abdominals',
  ARRAY['obliques', 'deltoids']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a kettlebell in your right hand overhead.', 'Step:2 Before moving, rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the turn smooth instead of throwing the arms across the body.', 'Step:6 Return through center before turning to the other side.']::text[],
