  'hamstrings',
  ARRAY['quadriceps', 'glutes']::text[],
  ARRAY['Step:1 Take a seat on the edge of a bench or chair with your feet planted and your knees bent at a 90-degree angle.', 'Step:2 Recline slightly and place your hands on the edge of the bench or chair for support.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position.']::text[],
