  ARRAY['biceps', 'triceps', 'deltoids', 'core']::text[],
  ARRAY['Step:1 Begin by hanging from a pull-up bar with palms facing down, hands just beyond shoulder width.', 'Step:2 Brace your trunk and use a swinging motion to generate momentum.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
