  '2f2b9728-a11a-59f0-85ce-e06ee8c9467c',
  'knee pushup',
  'knee push-ups',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Start by kneeling on the floor, keeping your knees together. Place your hands on the floor in front of you, slightly wider than shoulder-width apart.', '2. Make sure your body forms a straight line from head to knees. Hands should be positioned below shoulders.', '3. Lower your torso towards the ground, bending your elbows while keeping your trunk stable. Keep your knees in contact with the floor.', '4. Push through your hands to return to the starting position. Be sure to maintain contraction of chest, shoulder and arm muscles at the top of the movement.', '5. Perform the desired number of repetitions, controlling the movement and maintaining good form.']::text[],
