(
  '14bca701-6223-54ae-87bc-9840dab82015',
  'chest knee stretch',
  'Knee to Chest Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15–30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously.']::text[],
  null,
  null,
