  'Knee Tuck Jump',
  'legs',
  'body only',
  'hamstrings',
  ARRAY['abductors', 'adductors', 'calves', 'glutes', 'quadriceps']::text[],
  ARRAY['Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.', 'Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.', 'Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend.']::text[],
