(
  '52d7a25f-87de-5c17-b9b9-f6e17cd0b858',
  'arm drill kneeling',
  'Kneeling Arm Drill',
  'shoulders',
  '',
  'shoulders',
  ARRAY['abdominals']::text[],
  ARRAY['This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.', 'Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.', 'As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.', 'Switch knees and repeat.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Arm_Drill/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '7ef5d270-d8c1-5dfe-bb02-83426cbe1b0a',
  'alternate cable crunch kneeling oblique twists',
  'Kneeling Cable Crunch With Alternating Oblique Twists',
  'core',
  'cable',
  'abdominals',
  '{}'::text[],
  ARRAY['Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.', 'Grab the rope with both hands and kneel approximately two feet back from the tower.', 'Position the rope behind your head with your hands by your ears.', 'Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.', 'Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.', 'Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same movement as before, but alternate the other elbow to the opposite knee.', 'Continue this series of movements to failure.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg',
  'image',
  'public_domain',
