  ARRAY['Step:1 Begin in a kneeling position with your hands on the ground, about shoulder width.', 'Step:2 Reach your legs behind you, resting on your toes, and lift your body into a plank position.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
