  ARRAY['Step:1 Begin by kneeling on the ground with your hands about shoulder width, fingers pointing forward.', 'Step:2 Reach your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
