  'bodyweight',
  'pectorals',
  ARRAY['triceps', 'deltoids']::text[],
  ARRAY['Step:1 Set yourself between two parallel bars with your arms extended and supporting your body weight.', 'Step:2 Before moving, lower your body by bending your elbows until your upper arms are parallel to the ground.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
