  'bodyweight',
  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Take a seat on the floor with your legs extended in front of you.', 'Step:2 Set your hands on the floor beside your hips, fingers pointing forward.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
