  'b718cbcb-6f25-53f0-87a4-ee79b5efbcff',
  '180 landmine',
  'landmine 180',
  'core',
  'barbell',
  'abdominals',
  ARRAY['obliques', 'quadriceps']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and hold the barbell with both hands ahead of your chest.', 'Step:2 Bend your knees slightly and rotate your torso to the right, swinging the barbell down toward your right hip.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the turn smooth instead of throwing the arms across the body.', 'Step:6 Return through center before turning to the other side.']::text[],
  'https://static.exercisedb.dev/media/QYysSLV.gif',
