),
(
  '6a16c6b7-0ff7-5852-826a-c6ebc0791940',
  'landmine lateral raise',
  'landmine lateral raise',
  'shoulders',
  'barbell',
  'deltoids',
  ARRAY['trapezius', 'upper back']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and knees soft.', 'Step:2 Take hold of the barbell with palms facing down, resting it on the front of your shoulders.', 'Step:3 Start with a manageable load and a small bend in the elbows.', 'Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Step:5 Stop near shoulder height rather than shrugging to lift higher.', 'Step:6 Lower the arms slowly to your sides without swinging the weight.']::text[],
  'https://static.exercisedb.dev/media/eXMFHww.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '3ee9ad7a-b7fb-5149-b34b-9c57f25fc4d9',
  'jammer landmine linear',
  'Landmine Linear Jammer',
  'shoulders',
  'barbell',
  'shoulders',
  ARRAY['abdominals', 'calves', 'chest', 'hamstrings', 'quadriceps', 'triceps']::text[],
  ARRAY['Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.', 'Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.', 'In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.', 'Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.', 'Return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_Linear_Jammer/0.jpg',
  'image',
