  'Lateral Cone Hops',
  'legs',
  'other',
  'adductors',
  ARRAY['abductors', 'calves', 'glutes', 'hamstrings', 'quadriceps']::text[],
  ARRAY['Position a number of cones in a row several feet apart.', 'Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.', 'Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.', 'Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.']::text[],
