(
  '15d48bbc-17f8-55cb-b5cc-1b2b60ee0605',
  'lateral raise',
  'Lateral Raises',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger.de'
),
