),
(
  '4618152c-37ca-580c-aef3-bbbd6041dc27',
  'lean planche',
  'lean planche',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['deltoids', 'pectorals', 'triceps']::text[],
  ARRAY['Step:1 Begin in a push-up position with your hands about shoulder width and your body straight.', 'Step:2 Brace your trunk and With control shift your weight forward, bringing your shoulders past your hands.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
  'https://static.exercisedb.dev/media/LYJodFS.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '815965b3-6297-5a3b-9136-42f8acd8cd23',
  'away cable lateral lean raise',
  'Lean-Away Cable Lateral Raise',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Set a cable pulley at the lowest position and attach a single handle. Stand side-on to the machine, hold the frame with your near hand and lean your body away so you hang at an angle. With the far hand, grasp the handle in front of your hips and raise your arm out to the side to shoulder height with a slight bend in the elbow. Lower slowly. The lean increases tension on the side delts at the bottom of the movement. Complete all reps, then switch sides.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
(
  '2e3e5f84-d632-5021-b971-e5300a2b6811',
  'boxing hook left',
  'left hook (boxing)',
  'shoulders',
  'bodyweight',
  'deltoids',
  ARRAY['biceps', 'triceps', 'forearms']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your knees soft.', 'Step:2 Keep the left hand up to protect your face and your right hand by your chin.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Pivot through the hips and feet as the left arm travels across at chest height.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
  'https://static.exercisedb.dev/media/hoXt6wv.gif',
