  'Left levator scapulae stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Start standing up or sitting down. Turn your head to the left, around 45 degrees or just above your nipple. Place your right hand behind your back or sit on it. Take your left hand and use it to hold the back of your head. Lean your head down slightly.', 'Steps:', '1. After assuming the starting position, press your head against your left hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.']::text[],
