  'Left neck stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Sit or stand with your back straight.', 'Steps:', '1. Tilt your head to the side.', '2. Take the hand closer to your head and use it to grab your head from the other side.', '3. Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still.', '4. Maintain this tension until the end of the exercise.']::text[],
