(
  '42296fce-7048-51ef-92f2-170c6ad282b2',
  'extension leg',
  'Leg Extension',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The leg extension is a resistance weight training exercise that targets the quadriceps muscle in the legs. The exercise is done using a machine called the Leg Extension Machine. There are various manufacturers of these machines and each one is slightly different. Most gym and weight rooms will have the machine in their facility. The leg extension is an isolated exercise targeting one specific muscle group, the quadriceps. It should not be considered as a total leg workout, such as the squat or deadlift. The exercise consists of bending the leg at the knee and extending the legs, then lowering them back to the original position.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'BFad07'
),
(
  '637cfd80-b12a-55ba-a1f4-011637f60bb6',
  'extension isometric leg',
  'Leg Extension Isometric',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['An isometric leg extension is a strengthening exercise where you contract your quadriceps muscles against an immovable resistance without changing the length of the muscle or moving your knee joint.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'HexoctusEngineering'
),
(
  '1e1f8c4d-dd9a-5ff2-9be1-e84ded7b63f9',
  'extensions leg',
  'Leg Extensions',
  'legs',
  'machine',
  'quadriceps',
  '{}'::text[],
  ARRAY['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.', 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.', 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.', 'Repeat for the recommended amount of times.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '8ee1f5da-4873-5eef-b899-6fbb7105c166',
  'leg lift',
  'Leg Lift',
  'legs',
  'body only',
  'glutes',
  ARRAY['hamstrings']::text[],
  ARRAY['While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.', 'With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.', 'Slowly bring the raised leg back to the floor as you breathe in.', 'Repeat for the recommended amount of repetitions.', 'Repeat the movement with the opposite leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Lift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'ccc7c617-da5c-5c64-a4be-31808f8e799c',
  'leg press',
  'Leg Press',
  'legs',
  'machine',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development, however you can choose any of the three stances described in the foot positioning section).', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
