(
  '4767cc04-512c-5689-a520-c5e2637eadf8',
  'leg narrow press',
  'Leg Presses (narrow)',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The exercise is very similar to the wide leg press:', 'Sit on the machine and put your feet on the platform so far apart that you could just put another foot in between them. The feet are parallel and point up.', 'Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.']::text[],
