  'bench leg pull',
  'leg pull in flat bench',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors', 'erector spinae']::text[],
  ARRAY['Step:1 Take a seat on a flat bench with your legs extended straight out in front of you.', 'Step:2 Set your hands on the bench beside your hips for support.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position.']::text[],
