(
  '65bcb796-ed81-5282-a49e-ad4d20767628',
  'leg pull',
  'Leg Pull-In',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.', 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.', 'Return to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Pull-In/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
