  'leg up hamstring stretch',
  'legs',
  'bodyweight',
  'hamstrings',
  ARRAY['glutes']::text[],
  ARRAY['Step:1 Settle onto your back with your legs extended.', 'Step:2 Bend one knee and bring it toward your chest, holding onto your thigh or shin.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
