  'legs',
  'machine',
  'quadriceps',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.', 'Return the weight to the starting position.']::text[],
