  ARRAY['lats']::text[],
  ARRAY['Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position.', 'For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[],
