),
(
  'e6332a20-2265-52b7-b649-77d2af4cd3c0',
  'crunch levitation',
  'Levitation Crunch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['For', 'this top down movement, we’re trying to move the upper torso without moving the', 'lower torso. Start lying on the ground with feet flat on the floor and crossed', 'arms above your head with hands behind head. Lift upper body up and clear your', 'shoulder blades off the ground and then hold and pause at the top for a one or', 'two count. Try to make the upper abs work and hold that contraction for 10 good', 'quality reps.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Moffi'
),
(
  '3b9b43ff-b035-5003-8bb9-694465afcff2',
  '11 limber',
  'Limber 11',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Limber 11', 'Source: Joe DeFranco', '1. Foam Roll IT Band [soft_tissue] - 10-15 passes', '2. Foam Roll Adductors [soft_tissue] - 10-15 passes', '3. SMR Glutes (lax ball) [soft_tissue] - 30 sec-2 min', '4. Bent-knee Iron Cross [dynamic] - 5-10 reps each side', '5. Roll-overs into V-sits [dynamic] - 10 reps', '6. Rocking Frog Stretch [dynamic] - 10 reps', '7. Fire Hydrant Circles [dynamic] - 10 forward / 10 backward', '8. Mountain Climbers [dynamic] - 10 reps each leg', '9. Cossack Squats [dynamic] - 5-10 reps each side', '10. Seated Piriformis Stretch [isometric] - 20-30 sec each side', '11. Rear-foot-elevated Hip Flexor Stretch [dynamic + 3s hold] - 5-10 reps each side']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Pete-E automation'
),
(
  'c879b59a-06fb-53fd-babf-cf203fc4d332',
  '3 linear part start technique',
  'Linear 3-Part Start Technique',
  'legs',
  '',
  'hamstrings',
  ARRAY['calves', 'quadriceps']::text[],
  ARRAY['This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.', 'Place your right hand onto the line, and thing bring your nose close to your left knee.', 'Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.', 'Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_3-Part_Start_Technique/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'b30ee60d-bea5-57ff-8850-7cf1ba657d79',
  'acceleration drill linear wall',
  'Linear Acceleration Wall Drill',
  'legs',
  '',
  'hamstrings',
  ARRAY['calves', 'glutes', 'quadriceps']::text[],
  ARRAY['Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.', 'Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.', 'Switch legs, raising the opposite knee, and then attacking the ground straight down.', 'Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Acceleration_Wall_Drill/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '1ff7b7b0-65c0-5d97-9cc3-a8a798dd9bd3',
  'depth jump linear',
  'Linear Depth Jump',
  'legs',
  'other',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.', 'To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.', 'Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.', 'Land softly, asborbing the impact through the legs.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Depth_Jump/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'a87ae404-6131-57f7-b470-094d16f2c4c4',
  'lift log',
  'Log Lift',
  'shoulders',
  'other',
  'shoulders',
  ARRAY['abdominals', 'chest', 'glutes', 'hamstrings', 'lower back', 'middle back', 'quadriceps', 'traps', 'triceps']::text[],
  ARRAY['Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.', 'Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.', 'Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Log_Lift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '6e3b34ae-8dfb-5f45-9bdc-6aeb6747d9e8',
  'bridge london',
  'london bridge',
  'back',
  'rope',
  'upper back',
  ARRAY['deltoids', 'biceps', 'forearms']::text[],
  ARRAY['Step:1 Connect the rope to a high anchor point.', 'Step:2 Face the away from the anchor point from a stable stance with feet about shoulder width.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Bring the elbows back without jerking the torso.', 'Step:6 Reach the arms forward again without letting the torso lurch.']::text[],
  'https://static.exercisedb.dev/media/bLyQokI.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '074bd896-6b83-52b7-a9de-08e65d8ca825',
  'bridges london',
  'London Bridges',
  'back',
  'other',
  'lats',
  ARRAY['biceps', 'forearms', 'middle back']::text[],
  ARRAY['Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.', 'Stand on the bar, using the rope to balance yourself. This will be your starting position.', 'Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.', 'Keeping your body straight, reverse the motion, going hand over hand back to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/London_Bridges/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '96fab38a-1110-5269-9287-ad0181d41495',
  'long lunge pulse stretch',
  'Long Lunge Pulse Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Hold the resistance band (or any other rope-like object, the elasticity is not necessary) above your head, between your hands, with your arms straight. Pull it taught to engage your lats.', '2. Step forwards into a lunge, dropping until your knee is almost touching the floor.', '3. Slowly and controlledly pulse your body up and down by about an inch. Repeat for required reps.', '4. Repeat for other leg.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Croak6728'
),
(
  'd1d5f135-f7fa-5826-9790-dc4199003088',
  'long low pulley row',
  'Long-Pulley (low Row)',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.']::text[],
