  'ceiling looking',
  'Looking At Ceiling',
  'legs',
  '',
  'quadriceps',
  '{}'::text[],
  ARRAY['Kneel on the floor, holding your heels with both hands.', 'Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back.']::text[],
