  'box low squat stance wide',
  'Low Box Squat - Wide Stance',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Unrack the bar and set your stance wide, beyond your hips. Push your hips back and sit down to a box that takes you below parallel. Sit completely down, do not touch and go. Then explosively stand up. Stay tight in your upper back and torso throughout the movement.']::text[],
