(
  'f2956377-a67d-5f4e-87d9-ba36aa16a597',
  'cable crossover low',
  'Low Cable Crossover',
  'chest',
  'cable',
  'chest',
  ARRAY['shoulders']::text[],
  ARRAY['To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.', 'Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.', 'With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.', 'Return your arms back to the starting position after a brief pause.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Crossover/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'b4b1a19a-f3f6-53d8-afe8-78dce72c2f23',
  'cable extension low triceps',
  'Low Cable Triceps Extension',
  'triceps',
  'cable',
  'triceps',
  '{}'::text[],
  ARRAY['Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.', 'Grab the outside of the rope ends with your palms facing each other (neutral grip).', 'Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.', 'As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.', 'As you breathe in slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Triceps_Extension/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'a933db59-473d-539c-b3e2-f6c92eb6e649',
  'bridge floor glute low',
  'low glute bridge on floor',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings', 'core']::text[],
  ARRAY['Step:1 Settle onto your back with your knees bent and feet planted.', 'Step:2 Set your arms by your sides, palms facing down.', 'Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Step:4 Press through the feet and lift your hips until your torso and thighs line up.', 'Step:5 Stop when the hips line up with the torso, do not arch higher through the lower back.', 'Step:6 Lower the hips steadily and keep the feet planted for the next lift.']::text[],
  'https://static.exercisedb.dev/media/u0cNiij.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '5b47fa96-a6de-5a9e-a16b-5706031d85d1',
  'cable fly low pulley',
  'Low Pulley Cable Fly',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Adjust the cable machine: Set the pulley to the lowest setting possible.', 'Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists.', 'Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise.', 'Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there''s slight tension on the cables.', 'Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you''re giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest.', 'Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles.', 'Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level.', 'Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'FEFFO'
),
(
  '5ee4c841-3b73-51a6-a985-f40b16cc2e23',
  'low neck pulley row',
  'Low Pulley Row To Neck',
  'shoulders',
  'cable',
  'shoulders',
  ARRAY['biceps', 'middle back', 'traps']::text[],
  ARRAY['Sit on a low pulley row machine with a rope attachment.', 'Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.', 'While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.', 'After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Pulley_Row_To_Neck/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '50d4ab50-19e6-53e9-9325-498ba2dea60c',
  'cable cross low nb over',
  'Low-Cable Cross-Over - NB',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'JackSparrow'
),
(
  '43d94715-a1f3-5e20-950c-068e288350a7',
  'back curl lower',
  'lower back curl',
  'back',
  'bodyweight',
  'erector spinae',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Step:1 Settle onto your stomach with your legs extended and your arms by your sides.', 'Step:2 Engage your glutes and hamstrings, and With control lift your upper body off the ground, curling your back upwards.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
  'https://static.exercisedb.dev/media/ANbbry2.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
