(
  '875b3d88-6f9c-5be5-a3aa-c43ee6f5008e',
  'back lower smr',
  'Lower Back-SMR',
  'back',
  'foam roll',
  'lower back',
  '{}'::text[],
  ARRAY['In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.', 'Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back-SMR/0.jpg',
