),
(
  '50c19236-4694-5cee-ab30-b43b62d78664',
  'lunge pass through',
  'Lunge Pass Through',
  'legs',
  'kettlebells',
  'hamstrings',
  ARRAY['calves', 'glutes', 'quadriceps']::text[],
  ARRAY['Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.', 'Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.', 'As you lunge, pass the kettlebell under your front leg to your opposite hand.', 'Pressing through the heel of your foot, return to the starting position.', 'Repeat the movement for the recommended amount of repetitions, alternating legs.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Pass_Through/0.jpg',
