),
(
  '672b3d4e-a03b-5dcb-b96a-48fdfa5a1dc8',
  'lunge sprint',
  'Lunge Sprint',
  'legs',
  'machine',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.', 'Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.', 'At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Sprint/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'f77805cc-f135-523c-9543-daf4b8872c2e',
  'jump lunge',
  'lunge with jump',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Begin by standing with your feet about shoulder width.', 'Step:2 Step forward with your right foot, lowering your body into a lunge position.', 'Step:3 Set your stance wide enough to balance before bending either knee.', 'Step:4 Step into the movement and bend both knees, keeping your front foot planted.', 'Step:5 Keep the front foot planted and avoid collapsing inward at the knee.', 'Step:6 Push through the lead foot to return to the start, then change legs as planned.']::text[],
  'https://static.exercisedb.dev/media/PM1PZjg.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
