  'lunges',
  'Lunges',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Stand with back straight.', 'Steps:', '1. Take a large step forward with your left leg.', '2. Bring your pelvis down until you almost touch the floor with your right knee.', '3. Bring your pelvis back up.', '4. Return to the starting position by stepping back.', '5. Repeat, switching legs each time.']::text[],
