(
  'aea5365c-8e1f-5e89-802b-f47634c41bd6',
  'lying quads side stretch',
  'lying (side) quads stretch',
  'legs',
  'bodyweight',
  'quadriceps',
  ARRAY['hamstrings']::text[],
  ARRAY['Step:1 Settle onto your side with your legs straight.', 'Step:2 Before moving, bend your top leg and grab your ankle or foot with your hand.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/BWnJR72.gif',
