  'AscendAPI'
),
(
  '2428c268-bdcb-5638-b5af-88e0bf9cbdb1',
  'bent groin leg lying',
  'Lying Bent Leg Groin',
  'legs',
  'other',
  'adductors',
  '{}'::text[],
  ARRAY['Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.', 'Attempt to squeeze your knees together, while your partner prevents any movement from occurring.', 'After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Bent_Leg_Groin/0.jpg',
