),
(
  'c304dad7-dcef-5fe8-99f7-eed4813afd31',
  'cable curl lying',
  'Lying Cable Curl',
  'biceps',
  'cable',
  'biceps',
  '{}'::text[],
  ARRAY['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.', 'Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.', 'With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.', 'While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.', 'After a second squeeze at the top of the movement, slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cable_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '13afd12b-f8fa-5f57-911f-e4b227c85ca2',
  'barbell cambered lying row',
  'Lying Cambered Barbell Row',
  'back',
  'barbell',
  'middle back',
  ARRAY['biceps', 'lats', 'traps']::text[],
  ARRAY['Place a cambered bar underneath an exercise bench.', 'Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.', 'As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.', 'After a second hold at the top, lower back down to the starting position slowly as you inhale.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cambered_Barbell_Row/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'f8464981-9c93-55e9-9f5e-c29b1857bd75',
  'bar closegrip curl high lying pulley',
  'Lying Close-Grip Bar Curl On High Pulley',
  'biceps',
  'cable',
  'biceps',
  '{}'::text[],
  ARRAY['Place a flat bench in front of a high pulley or lat pulldown machine.', 'Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.', 'Lie on your back with your head over the end of the bench.', 'Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.', 'As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.', 'Return to starting position slowly.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'a5389fa3-b5a0-5b5a-8cb3-c402181155fa',
  'barbell behind closegrip extension head lying triceps',
  'Lying Close-Grip Barbell Triceps Extension Behind The Head',
  'triceps',
  'barbell',
  'triceps',
  '{}'::text[],
  ARRAY['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.', 'As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '7f6ff55c-bf28-5597-851a-5fc701429339',
  'barbell chin closegrip lying press triceps',
  'Lying Close-Grip Barbell Triceps Press To Chin',
  'triceps',
  'e-z curl bar',
  'triceps',
  '{}'::text[],
  ARRAY['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.', 'As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '778cf72e-8e89-546c-8ba1-1b67d2007ed8',
  'crossover lying',
  'Lying Crossover',
  'legs',
  'body only',
  'abductors',
  '{}'::text[],
  ARRAY['Lie on your back with your legs extended.', 'Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.', 'Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.', 'After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Crossover/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '43020c37-ee88-5c7c-bcb0-ee1da39aac5e',
  'curl dumbbell lying',
  'Lying Dumbbell Curls',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Take a', 'dumbbell in each hand and lie backwards on a bench, similar to a classic chest press.', 'Let your arms hang down at your sides, with the dumbbells possibly touching the', 'floor. Now start to lift the dumbbells upwards until your forearms are', 'perpendicular to the ceiling. Slowly lower the dumbbells until they almost', 'touch the floor again. Keep your ellbows in place to minimize cheating.']::text[],
  null,
  null,
  'wger',
