  'Moffi'
),
(
  '84d804ca-3907-54b6-969e-37de3c7a7d00',
  'curl dumbbell leg lying',
  'Lying Dumbbell Leg Curl',
  'legs',
  'dumbbell',
  'hamstrings',
  ARRAY['glutes']::text[],
  ARRAY['Step:1 Lie face down on a flat bench with your knees just past its edge.', 'Step:2 Hold a light dumbbell securely between your feet and keep your hips on the bench.', 'Step:3 Brace your trunk and keep the thighs resting on the bench.', 'Step:4 Bend your knees to draw your heels toward your glutes without lifting the hips.', 'Step:5 Lower the weight slowly until the legs are nearly straight, then reset your grip before repeating.']::text[],
  'https://static.exercisedb.dev/media/FkBIE6a.gif',
