(
  '222d5311-1bd0-57c6-b211-858b06336297',
  'dumbbell extension lying tricep',
  'Lying Dumbbell Tricep Extension',
  'triceps',
  'dumbbell',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.', 'As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.', 'At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[],
