),
(
  '9dac475d-3947-59a2-a6b3-fbb78dc7f593',
  'down face lying neck plate resistance',
  'Lying Face Down Plate Neck Resistance',
  'neck',
  'other',
  'neck',
  '{}'::text[],
  ARRAY['Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.', 'While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes") as you breathe in.', 'Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Down_Plate_Neck_Resistance/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
