(
  '7238999e-4a95-53c5-a39e-098f6c2407e7',
  'glute lying',
  'Lying Glute',
  'legs',
  'body only',
  'glutes',
  ARRAY['abductors']::text[],
  ARRAY['Lie on your back with your partner kneeling beside you.', 'Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.', 'Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.', 'After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Glute/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '36565880-6b6b-5a3b-bb53-3858690fa492',
  'hamstring lying',
  'Lying Hamstring',
  'legs',
  'other',
  'hamstrings',
  ARRAY['calves']::text[],
  ARRAY['Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.', 'With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.', 'Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Hamstring/0.jpg',
  'image',
