  'f82cc2d1-40ba-5b4a-86bf-f0a5f372103c',
  'cuff lying rotator',
  'Lying Rotator Cuff Exercise',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['This is an excercise for problems with the rotator cuff. Primary Infraspinatus, secondary Teres Minor.', 'Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.']::text[],
  null,
