  'Trix'
),
(
  '782634ca-9c13-5306-a586-719b39a708b0',
  'bar lying row t',
  'Lying T-Bar Row',
  'back',
  'machine',
  'middle back',
  ARRAY['biceps', 'lats']::text[],
  ARRAY['Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.', 'Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.', 'Lift the bar off the rack and extend your arms in front of you. This will be your starting position.', 'As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.', 'After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_T-Bar_Row/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'db7e149c-f2bf-5b69-a1bf-395f52c57043',
  'extensions lying triceps',
  'Lying Triceps Extensions',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Starting position for this', 'practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.', '2. Begin with arms over your upper', 'chest and elbows bent back at about a 45-degree angle.', '3. First bend at the elbows and', 'then allow the upper arm to drop back, bringing the barbell/dumbbells behind your', 'head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to', 'ensure that you’re targeting the triceps.', '4. Keep the shoulder blades tucked', 'under, the elbows tight in toward your head and your core active during', 'this entire movement.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Moffi'
),
(
  '5cdc994f-5852-500a-8c0a-97671bd603db',
  'kickback lying triceps',
  'Lying Triceps Kickback',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Moffi'
),
(
  '088fd94b-c7a6-558f-8525-3c518df8faf5',
  'lying press triceps',
  'Lying Triceps Press',
  'triceps',
  'e-z curl bar',
  'triceps',
  '{}'::text[],
  ARRAY['Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.', 'Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.', 'As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.', 'At that point, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Triceps_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9d1873fd-97f0-5837-9c1a-9383ce9f13dc',
  'lying windshield wipers',
  'Lying Windshield Wipers',
  'core',
  'assisted',
  'abdominals',
  ARRAY['hip flexors', 'obliques']::text[],
  ARRAY['Step:1 Settle onto your back with your legs extended and your arms by your sides.', 'Step:2 Set your hands under your glutes for support.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift both legs, then lower them together toward one side without letting the shoulders roll off the floor.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Bring the legs back through center, then lower them toward the other side with the same control.']::text[],
  'https://static.exercisedb.dev/media/UGhRD1A.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
