  'leverage machine',
  'quadriceps',
  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Set the seat and foot platform of the leverage machine to your desired position.', 'Step:2 Take a seat on the machine with your back against the backrest and your feet on the foot platform.', 'Step:3 Set your feet firmly on the plate and keep the hips against the seat.', 'Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Bring the weight or body back to its starting position without rushing, switch sides when the set calls for it.']::text[],
