  ARRAY['Step:1 Set the leverage machine to your desired resistance level.', 'Step:2 Step onto the foot platform and grip the handles with palms facing down, just beyond shoulder width.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
