  ARRAY['Step:1 Set the machine to fit your body size and range of motion.', 'Step:2 Take a seat on the machine with your back against the pad and your feet secured.', 'Step:3 Secure the hips and feet on the support before lifting.', 'Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Step:5 Finish in a straight body line, before the lower back overarches.', 'Step:6 Ease back to the start before repeating.']::text[],
