  ARRAY['Step:1 Fit the seat to your body, then settle into the machine.', 'Step:2 Hold the handles with palms facing down, just beyond shoulder width.', 'Step:3 Sit tall and set the shoulders before drawing the handle down.', 'Step:4 Pull the handle down by driving your elbows toward your ribs, keep your torso steady.', 'Step:5 Pull with the elbows rather than leaning far back to move the handle.', 'Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[],
